import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name (case-insensitive).',
      inputSchema: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'Search term to match against product names (case-insensitive).',
          },
          limit: {
            type: 'integer',
            description: 'Maximum number of results to return (1 to 10). Defaults to 10.',
            minimum: 1,
            maximum: 10,
          },
        },
        required: ['query'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { query, limit } = args || {};

  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  let effectiveLimit = 10;
  if (limit !== undefined) {
    if (!Number.isInteger(limit) || limit < 1 || limit > 10) {
      throw new Error('limit must be an integer between 1 and 10');
    }
    effectiveLimit = limit;
  }

  const needle = query.toLowerCase();
  const matches = products.filter((p) => p.name.toLowerCase().includes(needle));
  const results = matches.slice(0, effectiveLimit);

  const text = results.map((p) => `${p.id}: ${p.name}`).join('\n');

  return {
    content: [{ type: 'text', text: text || 'No matching products found.' }],
  };
}

